scriptedOperation.script:
function run(input, params) {
  var transition = params.transition;
  if (typeof transition !== "string" || transition === "") {
    throw new org.nuxeo.ecm.core.api.NuxeoException("Missing the 'transition' parameter.");
  }
  var allowedTransitions = input.doc.getAllowedStateTransitions();
  if (allowedTransitions.contains(transition)) {
    input = Document.FollowLifecycleTransition(input, { 'value': transition });
  } else {
    Console.warn(input.title + " cannot follow transition <" + transition
                 + "> from state <" + input.lifeCycle + ">");
  }
  return input;
}

function run(input, params) {
  if (input["dcx:reference"]) {
    return input;
  }
  var dept = input["dcx:department"] || "GEN";
  var year = CurrentDate.format("yyyy");
  var prefix = "DC-" + dept + "-" + year + "-";

  // Count existing references for this department/year to derive the sequence.
  var siblings = Repository.ResultSetQuery(null, {
    'query': "SELECT COUNT(ecm:uuid) FROM DCControlledDocument "
           + "WHERE dcx:reference LIKE '" + prefix + "%' "
           + "AND ecm:isVersion = 0 AND ecm:isTrashed = 0"
  });
  var next = 1;
  if (siblings && siblings.size() > 0) {
    next = parseInt(siblings.get(0).get("COUNT(ecm:uuid)"), 10) + 1;
  }
  var seq = "000" + next;
  input["dcx:reference"] = prefix + seq.substring(seq.length - 4);
  if (!input["dcx:owner"]) {
    input["dcx:owner"] = currentUser.name;
  }
  if (!input["dcx:confidentiality"]) {
    input["dcx:confidentiality"] = "INTERNAL";
  }
  return input;
}

function run(input, params) {
  if (input.lifeCycle !== "draft") {
    throw new org.nuxeo.ecm.core.api.NuxeoException(
      "Only a draft can be submitted for review (current state: " + input.lifeCycle + ").");
  }

  var reviewers = params.reviewers;
  if (reviewers && reviewers.length) {
    input["dcx:reviewers"] = reviewers;
    for (var i = 0; i < reviewers.length; i++) {
      input = Document.AddPermission(input, {
        'permission': "DCReview",
        'username': reviewers[i],
        'acl': "local",
        'notify': false
      });
    }
  }

  input["dcx:submittedBy"] = currentUser.name;
  input["dcx:submittedOn"] = CurrentDate.date;
  input = Document.Save(input);
  input = javascript.utils_FollowTransitionIfPossible(input, { 'transition': "to_review" });
  Audit.LogEvent(input, {
    'event': "docucentral_submitted",
    'category': "DocuCentral",
    'comment': "Submitted for review by " + currentUser.name
  });
  return input;
}

function run(input, params) {
  if (input.lifeCycle !== "review") {
    throw new org.nuxeo.ecm.core.api.NuxeoException(
      "Only a document under review can be approved (current state: " + input.lifeCycle + ").");
  }
  input["dcx:approvedBy"] = currentUser.name;
  input["dcx:approvedOn"] = CurrentDate.date;
  input["dcx:rejectionReason"] = null;
  input = Document.Save(input);
  input = javascript.utils_FollowTransitionIfPossible(input, { 'transition': "to_approved" });
  Audit.LogEvent(input, {
    'event': "docucentral_approved",
    'category': "DocuCentral",
    'comment': params.comment || ("Approved by " + currentUser.name)
  });
  return input;
}

function run(input, params) {
  if (!params.reason) {
    throw new org.nuxeo.ecm.core.api.NuxeoException("A rejection reason is required.");
  }
  input["dcx:rejectionReason"] = params.reason;
  input = Document.Save(input);
  input = javascript.utils_FollowTransitionIfPossible(input, { 'transition': "back_to_draft" });
  Audit.LogEvent(input, {
    'event': "docucentral_rejected",
    'category': "DocuCentral",
    'comment': params.reason
  });
  return input;
}

function run(input, params) {
  if (input.lifeCycle !== "approved") {
    throw new org.nuxeo.ecm.core.api.NuxeoException(
      "Only an approved document can be published (current state: " + input.lifeCycle + ").");
  }
  var months = params.reviewCycleMonths || 12;
  var next = new Date();
  next.setMonth(next.getMonth() + months);

  input["dcx:effectiveDate"] = CurrentDate.date;
  input["dcx:nextReviewDate"] = next;
  input = Document.Save(input);
  input = javascript.utils_FollowTransitionIfPossible(input, { 'transition': "to_published" });
  input = Document.CreateVersion(input, { 'increment': "Major" });
  Audit.LogEvent(input, {
    'event': "docucentral_published",
    'category': "DocuCentral",
    'comment': "Published by " + currentUser.name + "; next review " + next
  });
  return input;
}

function run(input, params) {
  var overdue = Repository.Query(null, {
    'query': "SELECT * FROM DCControlledDocument "
           + "WHERE ecm:currentLifeCycleState = 'published' "
           + "AND dcx:nextReviewDate < DATE '" + CurrentDate.format("yyyy-MM-dd") + "' "
           + "AND ecm:isVersion = 0 AND ecm:isTrashed = 0"
  });
  Console.warn("DocuCentral: " + overdue.size() + " document(s) overdue for review.");
  for (var i = 0; i < overdue.size(); i++) {
    Audit.LogEvent(overdue.get(i), {
      'event': "docucentral_review_overdue",
      'category': "DocuCentral",
      'comment': "Review date passed: " + overdue.get(i)["dcx:nextReviewDate"]
    });
  }
}
